var draw = SVG().addTo(document.getElementById('container')).size('100%','100%');
draw.viewbox(0, 0, 640, 340);

/* ── Heap data (CLRS Fig. 19.2) ─────────────────────────────────────── */
var POS = {23:[60,70], 7:[170,70], 3:[290,70], 17:[430,70], 24:[540,70],
           18:[230,160], 52:[290,160], 38:[350,160], 30:[430,160],
           26:[510,160], 46:[580,160],
           39:[230,250], 41:[350,250], 35:[510,250]};
var MARKED = {18:1, 39:1, 26:1};
var PARENT = {18:3, 52:3, 38:3, 39:18, 41:38, 30:17, 26:24, 46:24, 35:26};
var CHILDREN = {3:[18,52,38], 18:[39], 38:[41], 17:[30], 24:[26,46], 26:[35]};
var roots = [23, 7, 3, 17, 24];
var hminKey = 3;
var R = 16;

var markers = {};
function markerFor(color, id) {
  var k = id || color;
  if (!markers[k]) {
    markers[k] = draw.marker(9, 9).attr({ orient: 'auto', refX: 7, refY: 4.5 })
      .path('M0,0 L9,4.5 L0,9 z').fill(color);
  }
  return markers[k];
}

function siblingList(k) {
  var p = PARENT[k];
  return p != null ? CHILDREN[p] : roots;
}
function pointersOf(k) {
  var L = siblingList(k), i = L.indexOf(k), n = L.length;
  return {
    p: PARENT[k] != null ? PARENT[k] : null,
    child: (CHILDREN[k] && CHILDREN[k].length) ? CHILDREN[k][0] : null,
    left: L[(i - 1 + n) % n],
    right: L[(i + 1) % n],
    singleton: n === 1
  };
}

var gTree = draw.group(), gPtr = draw.group(), gHmin = draw.group(), gHi = draw.group();
var nodeEls = {};

function drawNode(g, k) {
  var x = POS[k][0], y = POS[k][1], marked = !!MARKED[k];
  var grp = g.group().css('cursor', 'pointer');
  grp.circle(2 * R).center(x, y)
     .fill(marked ? '#000' : '#e3e3e3').stroke({ color: '#333', width: 1.2 });
  grp.text(String(k)).attr({ x: x, y: y, 'text-anchor': 'middle', 'dominant-baseline': 'central',
      'font-size': 15, fill: marked ? '#fff' : '#000', 'font-style': 'normal' });
  grp.on('mousemove', function (e) {
    showTooltip('key ' + k + (marked ? ' (marked)' : '') + ' — click to inspect its four pointers', e);
  }).on('mouseleave', hideTooltip)
    .on('click', function () { inspectNode(k); });
  nodeEls[k] = grp;
}

/* ── Panel (a): abstract tree view ──────────────────────────────────── */
function buildTree() {
  gTree.clear();
  gTree.text('(a)').attr({ x: 8, y: 70, 'dominant-baseline': 'central', 'font-size': 15 });
  gTree.line(20, 70, 620, 70).stroke({ color: '#555', width: 1.2, dasharray: '5,4' });
  for (var c in PARENT) {
    var p = PARENT[c];
    gTree.line(POS[p][0], POS[p][1], POS[c][0], POS[c][1])
         .stroke({ color: '#333', width: 1.4 });
  }
  roots.forEach(function (k) { drawNode(gTree, k); });
  [18,52,38,30,26,46,39,41,35].forEach(function (k) { drawNode(gTree, k); });
}

/* ── Panel (b): explicit pointer view ───────────────────────────────── */
function shorten(x1, y1, x2, y2, d1, d2) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy) || 1;
  return [x1 + dx / L * d1, y1 + dy / L * d1, x2 - dx / L * d2, y2 - dy / L * d2];
}
function arcArrow(g, x1, y1, x2, y2, bend, color, w) {
  var s = shorten(x1, y1, x2, y2, R + 2, R + 6);
  var mx = (s[0] + s[2]) / 2, my = (s[1] + s[3]) / 2 + bend;
  return g.path('M' + s[0] + ',' + s[1] + ' Q' + mx + ',' + my + ' ' + s[2] + ',' + s[3])
    .fill('none').stroke({ color: color, width: w || 1.2 })
    .attr('marker-end', 'url(#' + markerFor(color).id() + ')');
}
function selfLoop(g, x, y, color, w) {
  return g.path('M' + (x - 9) + ',' + (y - 13) +
    ' C' + (x - 24) + ',' + (y - 50) + ' ' + (x + 24) + ',' + (y - 50) + ' ' + (x + 9) + ',' + (y - 13))
    .fill('none').stroke({ color: color, width: w || 1.2 })
    .attr('marker-end', 'url(#' + markerFor(color).id() + ')');
}
function drawRing(g, list) {
  if (list.length === 1) { selfLoop(g, POS[list[0]][0], POS[list[0]][1], '#333'); return; }
  for (var i = 0; i < list.length; i++) {
    var a = POS[list[i]], b = POS[list[(i + 1) % list.length]];
    var dist = Math.abs(b[0] - a[0]);
    var bend = Math.min(34, 16 + dist * 0.05);
    arcArrow(g, a[0], a[1] - 7, b[0], b[1] - 7, -bend, '#333');   // right pointers
    arcArrow(g, b[0], b[1] + 7, a[0], a[1] + 7, bend, '#333');    // left pointers
  }
}
function buildPtr() {
  gPtr.clear();
  gPtr.text('(b)').attr({ x: 8, y: 70, 'dominant-baseline': 'central', 'font-size': 15 });
  drawRing(gPtr, roots);
  for (var p in CHILDREN) drawRing(gPtr, CHILDREN[p]);
  // bidirectional parent <-> child arrows
  for (var c in PARENT) {
    var par = PARENT[c], a = POS[par], b = POS[c];
    arcArrow(gPtr, a[0] + 4, a[1], b[0] + 4, b[1], 0, '#333');  // p.child
    arcArrow(gPtr, b[0] - 4, b[1], a[0] - 4, a[1], 0, '#333');  // child.p
  }
  var order = roots.concat([18,52,38,30,26,46,39,41,35]);
  order.forEach(function (k) { drawNode(gPtr, k); });
}

function buildHmin() {
  gHmin.clear();
  var x = POS[hminKey][0], y = POS[hminKey][1];
  gHmin.text('H.min').attr({ x: x, y: y - 62, 'text-anchor': 'middle',
    'font-size': 16, 'font-style': 'italic' });
  gHmin.path('M' + x + ',' + (y - 50) + ' L' + x + ',' + (y - R - 4))
    .stroke({ color: '#000', width: 1.6 }).fill('none')
    .attr('marker-end', 'url(#' + markerFor('#000').id() + ')');
}

/* ── Node inspection: highlight the four pointer fields ─────────────── */
var hiColors = { p: '#8e44ad', child: '#1e8449', left: '#c0392b', right: '#2471a3' };
function inspectNode(k) {
  hideTooltip();
  var pt = pointersOf(k);
  var fmt = function (v) { return v == null ? 'NIL' : String(v); };
  showPopup('Node ' + k,
    'parent = ' + fmt(pt.p) + ' · child = ' + fmt(pt.child) +
    ' · left = ' + fmt(pt.left) + ' · right = ' + fmt(pt.right) +
    (MARKED[k] ? ' · marked (lost a child since being linked)' : ' · unmarked') +
    '. The same four fields wire this node into its sibling ring and into the tree.');
  if (!ptrMode) return; // highlight arrows drawn in pointer view only
  gHi.clear();
  var x = POS[k][0], y = POS[k][1];
  function lab(tx, ty, txt, color) {
    gHi.text(txt).attr({ x: tx, y: ty, 'text-anchor': 'middle', 'font-size': 11,
      'font-style': 'italic', fill: color, 'paint-order': 'stroke',
      stroke: '#fff', 'stroke-width': 3 });
  }
  if (pt.p != null) {
    var a = POS[pt.p];
    arcArrow(gHi, x - 8, y, a[0] - 8, a[1], 0, hiColors.p, 2.4);
    lab((x + a[0]) / 2 - 12, (y + a[1]) / 2, 'p', hiColors.p);
  } else {
    lab(x, y - 24, 'p = NIL', hiColors.p);
  }
  if (pt.child != null) {
    var b = POS[pt.child];
    arcArrow(gHi, x + 8, y, b[0] + 8, b[1], 0, hiColors.child, 2.4);
    lab((x + b[0]) / 2 + 14, (y + b[1]) / 2, 'child', hiColors.child);
  } else {
    lab(x + 26, y + 4, 'child = NIL', hiColors.child);
  }
  if (pt.singleton) {
    selfLoop(gHi, x, y, hiColors.right, 2.4);
    lab(x, y - 46, 'left = right = self', hiColors.right);
  } else {
    var L = POS[pt.left], Rp = POS[pt.right];
    arcArrow(gHi, x, y + 8, L[0], L[1] + 8, 22, hiColors.left, 2.4);
    lab((x + L[0]) / 2, y + 34, 'left', hiColors.left);
    arcArrow(gHi, x, y - 8, Rp[0], Rp[1] - 8, -22, hiColors.right, 2.4);
    lab((x + Rp[0]) / 2, y - 34, 'right', hiColors.right);
  }
}

/* ── FIB-HEAP-INSERT: O(1) splice into the root list ────────────────── */
var insertQueue = [21, 2], inserting = false;
function trigger_insertAnimation() {
  if (inserting) return;
  if (!insertQueue.length) {
    showPopup('FIB-HEAP-INSERT', 'Demo keys used up. Reload the figure to insert again.');
    return;
  }
  if (!ptrMode) { toggle_viewMode(true); document.getElementById('viewModeInput').checked = true; }
  inserting = true;
  gHi.clear();
  var key = insertQueue.shift();
  var hi = roots.indexOf(hminKey);
  var leftNbr = roots[(hi - 1 + roots.length) % roots.length];
  var nx = (POS[leftNbr][0] + POS[hminKey][0]) / 2, ny = 70;
  POS[key] = [nx, ny];
  // Stage 1: new singleton fades in with its self-loop
  var ghost = draw.group().opacity(0);
  selfLoop(ghost, nx, ny, '#c0392b', 1.6);
  ghost.circle(2 * R).center(nx, ny).fill('#fdf2c8').stroke({ color: '#c0392b', width: 1.6 });
  ghost.text(String(key)).attr({ x: nx, y: ny, 'text-anchor': 'middle',
    'dominant-baseline': 'central', 'font-size': 15 });
  ghost.animate(400).opacity(1).after(function () {
    // Stage 2: splice — rewire left/right pointers only
    roots.splice(hi, 0, key);
    ghost.remove();
    buildPtr();
    var flash = draw.group();
    arcArrow(flash, POS[leftNbr][0], 63, nx, 63, -22, '#c0392b', 2.6);
    arcArrow(flash, nx, 63, POS[hminKey][0], 63, -22, '#c0392b', 2.6);
    arcArrow(flash, POS[hminKey][0], 77, nx, 77, 22, '#c0392b', 2.6);
    arcArrow(flash, nx, 77, POS[leftNbr][0], 77, 22, '#c0392b', 2.6);
    // Stage 3: H.min moves only if the new key is smaller
    setTimeout(function () {
      if (key < hminKey) {
        hminKey = key;
        buildHmin();
        gHmin.select('text').first().attr({ fill: '#c0392b' });
        showPopup('FIB-HEAP-INSERT(' + key + ')',
          'Spliced ' + key + ' into the root list left of the old minimum with four pointer changes — O(1). ' +
          'Because ' + key + ' < 3, H.min now points at the new node.');
      } else {
        showPopup('FIB-HEAP-INSERT(' + key + ')',
          'Spliced ' + key + ' into the root list left of H.min with four pointer changes — O(1), no tree restructuring. ' +
          key + ' ≥ 3, so H.min stays put.');
      }
      setTimeout(function () { flash.animate(500).opacity(0).after(function () { flash.remove(); }); inserting = false; }, 900);
    }, 700);
  });
}

/* ── View toggle + demo step player ─────────────────────────────────── */
var ptrMode = false;
function toggle_viewMode(on) {
  ptrMode = on;
  gHi.clear();
  if (on) { gTree.hide(); gPtr.show(); }
  else { gPtr.hide(); gTree.show(); }
}
var steps = [
  { title: 'The abstract heap', ptr: false,
    narration: 'Five min-heap-ordered trees share one root list (dashed line), and H.min points at the smallest root, 3. Black nodes 18, 39, and 26 are marked — each has lost a child since being linked to its parent.' },
  { title: 'Same heap, real pointers', ptr: true,
    narration: 'Pointer view: the dashed line is really a circular doubly linked root list, and each child group (18↔52↔38, 26↔46) is its own ring, with bidirectional parent/child arrows and self-loops on singletons.' },
  { title: 'Inspect four pointers', ptr: true,
    narration: 'Click any node — try 3 or 18 — to highlight its parent (purple), child (green), left (red), and right (blue) pointers. The same four fields serve the root list and every child list.' },
  { title: 'Constant-time insert', ptr: true,
    narration: 'Press FIB-HEAP-INSERT: a new node is spliced into the root list next to H.min by rewiring a handful of pointers (red) — no restructuring. H.min moves only when the new key beats 3 (insert 2 second!).' }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  document.getElementById('viewModeInput').checked = s.ptr;
  toggle_viewMode(s.ptr);
  document.getElementById('demoNarration').textContent = s.title + ' — ' + s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + '/' + steps.length;
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

buildTree(); buildPtr(); buildHmin();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A Fibonacci heap is a collection of min-heap-ordered trees whose roots live in a circular doubly linked root list with an H.min pointer, and the abstract tree view is just shorthand for an explicit pointer structure where every node has parent, child, left, and right pointers.
KEY INSIGHT (what students should walk away understanding): The Fibonacci heap's power comes from lazy structure: roots and siblings live in circular doubly linked lists, so inserting a node or adding a tree to the root list costs only a constant number of pointer changes.
DEMO STEPS: 4 guided steps — implement the step player in #ui

